#!/usr/bin/env python3
from pwn import *

def trace_execution(proc):
    lines = []
    while True:
        try:
            line = proc.recvline(timeout=0.5)
            if not line:
                break
            lines.append(line)
        except EOFError:
            break
    return b''.join(lines)

def test_input(input_data):
    try:
        p = process('./ctf_files/prog')
        p.sendline(input_data)
        output = trace_execution(p)
        p.close()
        return output
    except:
        return None

def brute_force_char(known_prefix, pos):
    results = []
    for c in range(32, 127):
        test_str = known_prefix + bytes([c])
        if pos > len(test_str):
            test_str += b'A' * (pos - len(test_str))
        result = test_input(test_str)
        if result and b"Incorrect" not in result:
            results.append((c, result))
    return results

def main():
    context.log_level = 'error'
    known = b''

    # First try common flag formats
    print("[*] Testing common formats...")
    test_cases = [
        b'csawctf{',
        b'CSAWCTF{',
        b'flag{',
        b'FLAG{'
    ]

    for test in test_cases:
        result = test_input(test)
        print(f"Testing {test}: {result}")

    # Try to find flag length
    print("\n[*] Finding input length...")
    max_len = 100
    responses = {}

    for i in range(1, max_len):
        test_input_data = b'A' * i
        result = test_input(test_input_data)
        if result:
            responses[i] = result
            if b"Correct" in result:
                print(f"Found interesting response at length {i}")
                print(result)

    # Try character frequency analysis
    print("\n[*] Testing character patterns...")
    test_patterns = [
        bytes([x for x in range(65, 91)]),  # A-Z
        bytes([x for x in range(97, 123)]), # a-z
        bytes([x for x in range(48, 58)]),  # 0-9
        b'_-{}[]()$#@!',
    ]

    for pattern in test_patterns:
        for c in pattern:
            test_str = bytes([c]) * 20
            result = test_input(test_str)
            if result and b"Incorrect" not in result:
                print(f"Found interesting character: {chr(c)}")
                print(result)

if __name__ == '__main__':
    main()

